/**
 * The TRACKED agent digests, read for the machine artifacts.
 *
 * `tokens.mjs` reads the built token layer (`dist/css/tokens.json`) — every
 * emitted `--al-*` name with its resolved value. That is the right source for a
 * table of values, and it is a build artifact: absent in a bare clone.
 *
 * These two files are the other half, and they are COMMITTED
 * (`.altitude/ai-readiness/*.json`, regenerated by
 * `scripts/ai-readiness/build-tokens-digest.mjs` /
 * `build-cem-digest.mjs` and drift-gated in CI). They carry the part a values
 * table cannot: the naming CONVENTIONS a token name must obey, and the
 * `notExistDoNotInvent` list — names agents have been observed inventing, each
 * of which looks plausible and silently falls back to the inherited value when
 * written. That list is the whole reason the prescriptive llms artifacts exist,
 * so it is read from the file rather than restated here.
 *
 * A missing digest is reported as unavailable, never as "no rules" — same
 * refusal-to-blur as `a11y.mjs`.
 */
import fs from 'node:fs';
import path from 'node:path';
import { repoRoot } from './repo-root.mjs';

const DIGEST_DIR = path.join(repoRoot(), '.altitude', 'ai-readiness');

function read(name) {
  const file = path.join(DIGEST_DIR, name);
  try {
    return { data: JSON.parse(fs.readFileSync(file, 'utf8')), artifact: `.altitude/ai-readiness/${name}`, reason: null };
  } catch (error) {
    return {
      data: null,
      artifact: `.altitude/ai-readiness/${name}`,
      reason:
        error.code === 'ENOENT'
          ? `${name} has not been generated in this checkout (it is tracked in git — restore it, or run \`pnpm --filter @southleft/al-web-components build\`).`
          : `${name} could not be read: ${error.message}`,
    };
  }
}

export const TOKENS_DIGEST = read('tokens-digest.json');
export const CEM_DIGEST = read('cem-digest.json');

/** The naming rules a token name must obey, or `null` when the digest is absent. */
export const TOKEN_CONVENTIONS = TOKENS_DIGEST.data?.conventions ?? null;

/** Names that do NOT exist and have been observed being invented. */
export const DO_NOT_INVENT = TOKEN_CONVENTIONS?.notExistDoNotInvent ?? [];

/**
 * Per-tag sanctioned patterns a reviewer must not report as violations. The CEM
 * digest is keyed by tag at the top level, not nested under a `components` key.
 */
export function doNotFlagFor(tag) {
  return CEM_DIGEST.data?.[tag]?.doNotFlag ?? [];
}

/** Every tag that declares at least one sanctioned pattern, with its rules. */
export function allDoNotFlag() {
  return Object.entries(CEM_DIGEST.data ?? {})
    .filter(([, entry]) => Array.isArray(entry?.doNotFlag) && entry.doNotFlag.length)
    .map(([tag, entry]) => ({ tag, rules: entry.doNotFlag }));
}
